class Solution {
public:
    int countHillValley(vector<int>& nums) {
        int n = nums.size();
        int count = 0;
        int prev = nums[0];
        for (int i = 1; i < n; i++) {
            if (nums[i] != nums[i - 1]) {
                if (i >= 2) {
                    int mid = nums[i - 1];
                    if ((mid > prev && mid > nums[i]) ||
                        (mid < prev && mid < nums[i])) {
                        count++;
                    }
                }
                prev = nums[i - 1];
            }
        }
        return count;
    }
};
